private static Packet<?> createVanillaPacket(Object message, PacketDistributor.PacketTarget packetTarget, Object ... messages) {
    if (messages == null || messages.length == 0) {
        return INSTANCE.toVanillaPacket(message, packetTarget.getDirection());
    }
    ArrayList<Packet> packets = new ArrayList<Packet>();
    packets.add(INSTANCE.toVanillaPacket(message, packetTarget.getDirection()));
    for (Object bundleMessage : messages) {
        packets.add(INSTANCE.toVanillaPacket(bundleMessage, packetTarget.getDirection()));
    }
    return new ClientboundBundlePacket(packets);
}

