}

@Override
public void resetLivingAnimations() {
    super.resetLivingAnimations();
    this.compositeLivingAnimations.clear();
    this.defaultLivingAnimations.forEach((key, val) -> this.addLivingAnimation((LivingMotion)key, (AssetAccessor<? extends StaticAnimation>)val));
    this.defaultCompositeLivingAnimations.forEach((key, val) -> this.addLivingAnimation((LivingMotion)key, (AssetAccessor<? extends StaticAnimation>)val));
}

